glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_INSTANCING
  in vec4 a_matWorld0;
  in vec4 a_matWorld1;
  in vec4 a_matWorld2;
#else
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec3 a_normal;
in vec2 a_texCoord;
out vec2 v_uv;
out vec3 v_worldNormal;
out vec3 v_worldPos;
vec4 vert () {
  mat4 matWorld;
  #if USE_INSTANCING
    matWorld = mat4(
      vec4(a_matWorld0.xyz, 0.0),
      vec4(a_matWorld1.xyz, 0.0),
      vec4(a_matWorld2.xyz, 0.0),
      vec4(a_matWorld0.w, a_matWorld1.w, a_matWorld2.w, 1.0)
    );
  #else
    matWorld = cc_matWorld;
  #endif
  vec4 worldPos = matWorld * vec4(a_position, 1.0);
  v_worldPos = worldPos.xyz;
  v_uv = a_texCoord;
  v_worldNormal = normalize((matWorld * vec4(a_normal, 0.0)).xyz);
  return cc_matProj * cc_matView * worldPos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec2 v_uv;
in vec3 v_worldNormal;
in vec3 v_worldPos;
layout(std140) uniform CubeColor {
  vec4 baseColor;
  vec4 arrowColor;
  vec4 specularParams;
};
uniform sampler2D mainTexture;
vec4 frag () {
  vec4 texel = texture(mainTexture, v_uv);
  float mask = (texel.r + texel.g + texel.b) / 3.0;
  mask = smoothstep(0.45, 0.55, mask);
  vec3 albedo = mix(arrowColor.rgb, baseColor.rgb, mask);
  vec3 normal = normalize(v_worldNormal);
  vec3 lightDir = normalize(-cc_mainLitDir.xyz);
  vec3 viewDir  = normalize(cc_cameraPos.xyz - v_worldPos);
  vec3 halfDir  = normalize(lightDir + viewDir);
  float NdotL = dot(normal, lightDir) * 0.5 + 0.5;
  vec3 diffuse = albedo * cc_mainLitColor.rgb * cc_mainLitColor.w * NdotL;
  float intensity = specularParams.x;
  float shininess = specularParams.y;
  float NdotH = max(dot(normal, halfDir), 0.0);
  vec3 specular = cc_mainLitColor.rgb * cc_mainLitColor.w * intensity * pow(NdotH, shininess);
  vec3 ambient = albedo * cc_ambientSky.rgb * cc_ambientSky.w;
  return vec4(ambient + diffuse + specular, 1.0);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
