glsl1.frag:
precision highp float;
uniform highp vec4 cc_cameraPos;
  uniform mediump vec4 cc_mainLitDir;
  uniform mediump vec4 cc_mainLitColor;
  uniform mediump vec4 cc_ambientSky;
varying vec2 v_uv;
varying vec3 v_worldNormal;
varying vec3 v_worldPos;
   uniform vec4 baseColor;
   uniform vec4 arrowColor;
   uniform vec4 specularParams;
uniform sampler2D mainTexture;
vec4 frag () {
  vec4 texel = texture2D(mainTexture, v_uv);
  float mask = (texel.r + texel.g + texel.b) / 3.0;
  mask = smoothstep(0.45, 0.55, mask);
  vec3 albedo = mix(arrowColor.rgb, baseColor.rgb, mask);
  vec3 normal = normalize(v_worldNormal);
  vec3 lightDir = normalize(-cc_mainLitDir.xyz);
  vec3 viewDir  = normalize(cc_cameraPos.xyz - v_worldPos);
  vec3 halfDir  = normalize(lightDir + viewDir);
  float NdotL = dot(normal, lightDir) * 0.5 + 0.5;
  vec3 diffuse = albedo * cc_mainLitColor.rgb * cc_mainLitColor.w * NdotL;
  float intensity = specularParams.x;
  float shininess = specularParams.y;
  float NdotH = max(dot(normal, halfDir), 0.0);
  vec3 specular = cc_mainLitColor.rgb * cc_mainLitColor.w * intensity * pow(NdotH, shininess);
  vec3 ambient = albedo * cc_ambientSky.rgb * cc_ambientSky.w;
  return vec4(ambient + diffuse + specular, 1.0);
}
void main() { gl_FragColor = frag(); }
